import numpy as np
import json

def rot90_cw(grid): 
    return np.rot90(np.array(grid), k=-1).tolist()

def rot270(grid):  # 90° CCW
    return np.rot90(np.array(grid), k=1).tolist()

def rot180(grid):
    return np.rot90(np.array(grid), k=2).tolist()

def transform(grid):
    inp = np.array(grid)
    n = len(inp)
    out = np.zeros((n*3, n*3), dtype=int)

    for i in range(n):
        for j in range(n):
            if i == 1 and j == 1:  # center (1,1) stays same
                out[i*3:(i+1)*3, j*3:(j+1)*3] = inp
            elif (i % 2 == 0 and j % 2 == 0) or (i % 2 == 1 and j % 2 == 1):  # corners
                out[i*3:(i+1)*3, j*3:(j+1)*3] = rot180(inp)
            elif i == 0 or i == 2:  # top/bottom edges
                out[i*3:(i+1)*3, j*3:(j+1)*3] = rot90_cw(inp)
            else:  # left/right edges
                out[i*3:(i+1)*3, j*3:(j+1)*3] = rot270(inp)

    return out.tolist()

# Submit for test input
